using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckKeepaway {
public sealed class KeepawaySmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> lines=new List<string>();Keyboard keyboard;InputSettings original,probe;KeepawayMatch m;string folder;bool done,error;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsKeepaway")<0)return;var g=new GameObject("Keepaway native physical validation");DontDestroyOnLoad(g);g.AddComponent<KeepawaySmoke>();}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("KeepawayEvidence");Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Keepaway software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;lines.Add("ERROR "+s);}}
 void Check(bool b,string label){if(!b)throw new Exception(label);lines.Add("PASS "+label);Debug.Log("KEEPAWAY_NATIVE_PASS "+label);}void Note(string label){lines.Add(label);Debug.Log("KEEPAWAY_NATIVE_EVIDENCE "+label);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label+" carrier="+m.Carrier+" steals="+m.Steals+" scores="+m.Standings);yield return null;}}
 void Update(){if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){lines.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;Time.timeScale=1;if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);File.WriteAllLines(Path.Combine(folder,"results.txt"),lines);Application.Quit(code);}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SceneManager.LoadScene("TruckKeepaway");yield return Delay(.5f);m=FindAnyObjectByType<KeepawayMatch>();m.setup.count=4;for(int i=0;i<4;i++)m.setup.players[i].source=BowlingSource.Keyboard;Check(m.StartMatch(),"physical four-truck source fixture starts");for(int i=0;i<4;i++)m.trucks[i].Prepare(new Vector3(i%2==0?-18:18,.48f,i<2?-12:12),Quaternion.identity);m.trucks[0].Prepare(new Vector3(0,.48f,-4),Quaternion.identity);m.trucks[0].body.linearVelocity=Vector3.forward*7;yield return Wait(()=>m.Carrier==0,3,"actual neutral ball contact pickup");Check(m.Pickups==1&&m.ball.isKinematic&&!m.ballShape.enabled,"single ball attaches to one carrier");m.trucks[0].Prepare(new Vector3(0,.48f,0),Quaternion.identity);m.trucks[1].Prepare(new Vector3(0,.48f,-7),Quaternion.identity);yield return Delay(.9f);m.trucks[1].body.linearVelocity=Vector3.forward*8;yield return Wait(()=>m.Carrier==1,3,"fresh body collision steals");Check(m.Steals==1&&m.Blasts==1&&!m.alive[0]&&!m.trucks[0].visuals.gameObject.activeSelf,"ownership transfers before former carrier explodes");Check(m.CanAttack(1)&&m.ball.isKinematic&&FindObjectsByType<KeepawayBall>().Length==1,"one ball and one successful thief");int steals=m.Steals;yield return Delay(.4f);Check(m.Steals==steals&&m.Blasts==1,"blast/debris/sustained contact do not cause recursive steals");Check(m.possession[0]>0&&m.possession[1]>0,"possession persists for both former and current carriers");yield return Wait(()=>m.alive[0],3,"former carrier respawns");Check(m.shield[0]>Time.time&&!m.CanAttack(0),"visible respawn protection cannot attack");m.Pause();var pos=m.trucks[1].body.position;float score=m.possession[1];yield return Delay(.3f);Check(m.trucks[1].body.position==pos&&m.possession[1]==score,"pause preserves possession and live bodies");m.Resume();m.trucks[1].body.position=new Vector3(30,.48f,0);yield return Delay(.1f);Check(m.Carrier==-1&&!m.ball.isKinematic,"off-arena carrier drops a reachable neutral ball");Check(Mathf.Abs(m.ball.position.x)<m.arenaX&&Mathf.Abs(m.ball.position.z)<m.arenaZ,"recovery drop stays inside playable arena");
  for(int target=0;target<3;target++){m.SetupScreen();m.option=target;m.setup.count=4;for(int i=0;i<4;i++){m.setup.players[i].source=BowlingSource.AI;m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);}Check(m.StartMatch(),"four-AI cumulative "+m.Target+"s match starts");Time.timeScale=4;yield return Wait(()=>m.Finished,300,"complete AI possession match "+m.Target);Check(m.Winner>=0&&m.possession[m.Winner]==m.Target,"exact cumulative win threshold "+m.Target);Check(m.Steals>0&&m.Blasts==m.Steals,"natural AI match has actual steals/explosions "+m.Target);Note("AI target="+m.Target+" winner="+m.Winner+" steals="+m.Steals+" pickups="+m.Pickups+" scores="+m.Standings);Time.timeScale=1;Capture("result-"+m.Target);yield return Delay(.2f);}
  m.SetupScreen();Screen.SetResolution(1280,720,false);yield return Delay(.4f);Capture("setup-720");yield return Delay(.2f);Screen.SetResolution(1920,1080,false);yield return Delay(.4f);Check(m.StartMatch(),"rematch retains four competitors");yield return Delay(2);Capture("arena-1080");yield return Delay(.2f);SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"Keepaway scene lifecycle returns to collection");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
